#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    bool inside = false;
    string builder;
    int maxOutside = 0;
    int insideCount = 0;
    for (int i = 0; i < n; i++) {
        char c = s[i];
        if (c == '(') {
            if (!inside) {
                vector<string> outsideWords;
                size_t start = 0, end;
                while ((end = builder.find('_', start)) != string::npos) {
                    outsideWords.push_back(builder.substr(start, end - start));
                    start = end + 1;
                }
                outsideWords.push_back(builder.substr(start));
                for (const auto& word : outsideWords) {
                    maxOutside = max(maxOutside, (int)word.length());
                }
            }
            inside = true;
            builder.clear();
        } else if (c == ')') {
            inside = false;
            vector<string> insideWords;
            size_t start = 0, end;
            while ((end = builder.find('_', start)) != string::npos) {
                insideWords.push_back(builder.substr(start, end - start));
                start = end + 1;
            }
            insideWords.push_back(builder.substr(start));
            for (const auto& word : insideWords) {
                if (!word.empty()) {
                    insideCount++;
                }
            }
            builder.clear();
        } else {
            builder += c;
        }
    }
    vector<string> outsideWords;
    size_t start = 0, end;
    while ((end = builder.find('_', start)) != string::npos) {
        outsideWords.push_back(builder.substr(start, end - start));
        start = end + 1;
    }
    outsideWords.push_back(builder.substr(start));
    for (const auto& word : outsideWords) {
        maxOutside = max(maxOutside, (int)word.length());
    }
    cout << maxOutside << " " << insideCount << "\n";
    return 0;
}
